interface IProps {
  online: boolean;
  action?: (what: string) => void;
  sx?: SxProps;
}

export function HelpMenu(props: IProps) {
  const { online, action } = props;
  const { pathname } = useLocation();
  const [projType] = useGlobal('projType'); //verified this is not used in a function 2/18/25
  const [memory] = useGlobal('memory');
  const [anchorEl, setAnchorEl] = React.useState<null | HTMLElement>(null);
  const [shift, setShift] = React.useState(false);
  const [developer, setDeveloper] = useGlobal('developer');
  const [aboutOpen, setAboutOpen] = React.useState(false);
  const [topic, setTopic] = React.useState<string>();
  const { showMessage } = useSnackBar();
  const { getPlan } = usePlan();
  const t: IMainStrings = useSelector(mainSelector, shallowEqual);
  const getGlobal = useGetGlobal();
  const handleClick = (event: React.MouseEvent<HTMLElement>) => {
    setShift(event.shiftKey);
    setAnchorEl(event.currentTarget);
  };

  const handleHelp = (topic: string) => () => {
    setTopic(topic);
    setAnchorEl(null);
  };

  const handleReset = () => {
    setTopic(undefined);
  };

  const handleDownload = (url: string, inOffline?: boolean) => async () => {
    const loc = inOffline !== undefined ? inOffline : getGlobal('offline');
    const urlObj = new URL(url);
    const name = urlObj.pathname.split('/').pop() || '';
    const folder = await execFolder();
    const localPath = loc
      ? path.join(folder, 'help', name)
      : await dataPath(name, PathType.ZIP);
    if (!loc) {
      const err = await ipc?.downloadFile(url, localPath);
      if (err || !(await ipc?.exists(localPath))) {
        showMessage(`Failed to download ${name}`);
        setAnchorEl(null);
        return;
      }
    }
    launch(localPath, false);
    setAnchorEl(null);
    if (action) action('Download');
  };

  const handleSite = (site: string) => () => {
    if (!online) showMessage(t.reportWhenOnline);
    else launch(site, online);
  };

  const handleDeveloper = () => {
    const newVal = developer ? false : true;
    localStorage.setItem('developer', newVal.toString());
    setDeveloper(newVal);
    setAnchorEl(null);
  };

  const handleAbout = (visible: boolean) => () => {
    if (visible !== aboutOpen) setAboutOpen(visible);
    restoreScroll();
    setAnchorEl(null);
  };

  const handle = (what: string) => () => {
    setAnchorEl(null);
    if (action) {
      action(what);
    }
  };

  const spreadsheetTopic = '#t=Concepts%2FSpreadsheet_convention.htm';

  const planRec = React.useMemo(
    () => {
      const match = /\/plan\/([0-9a-f-]+)\/0/.exec(pathname);
      const planId =
        match &&
        (remoteIdGuid('plan', match[1] ?? '', memory?.keyMap as RecordKeyMap) ||
          match[1]);
      return planId && getPlan(planId);
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [pathname]
  );

  const sampleHref = React.useMemo(
    () => {
      if (!planRec) return '#';
      if (planRec.attributes.flat) {
        if (projType.toLowerCase() === 'scripture') {
          return API_CONFIG.flatSample;
        } else {
          return API_CONFIG.genFlatSample;
        }
      } else {
        if (projType.toLowerCase() === 'scripture') {
          return API_CONFIG.hierarchicalSample;
        } else {
          return API_CONFIG.genHierarchicalSample;
        }
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [planRec, projType]
  );

  const sampleDesc = React.useMemo(() => {
    if (!planRec) return '';
    if (planRec.attributes.flat) {
      if (projType.toLowerCase() === 'scripture') {
        return t.flatSample;
      } else {
        return t.genFlatSample;
      }
    } else {
      if (projType.toLowerCase() === 'scripture') {
        return t.hierarchicalSample;
      } else {
        return t.genHierarchicalSample;
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [planRec, projType, (planRec as Plan)?.attributes?.flat]);

  return (
    <div id="helpMenu">
      <IconButton
        aria-controls="customized-menu"
        aria-haspopup="true"
        onClick={handleClick}
      >
        <HelpOutlineIcon />
      </IconButton>
      <StyledMenu
        id="helpClose"
        anchorEl={anchorEl}
        keepMounted
        open={Boolean(anchorEl)}
        onClose={handle('Close')}
        sx={props?.sx}
      >
        <StyledMenuItem id="helpHelp" onClick={handleHelp('')}>
          <ListItemIcon>
            <HelpOutlineIcon />
          </ListItemIcon>
          <ListItemText primary={t.helpCenter} />
        </StyledMenuItem>
        {planRec && (
          <StyledMenuItem id="helpSheet" onClick={handleHelp(spreadsheetTopic)}>
            <ListItemIcon>
              <HelpOutlineIcon />
            </ListItemIcon>
            <ListItemText primary={t.helpSpreadsheet} />
          </StyledMenuItem>
        )}
        {planRec && !isElectron && (
          <a
            href={sampleHref}
            style={{ textDecoration: 'none' }}
            target="_blank"
            rel="noopener noreferrer"
          >
            <StyledMenuItem id="helpSampleOn">
              <ListItemIcon>
                <DownloadIcon />
              </ListItemIcon>
              <ListItemText primary={sampleDesc} />
            </StyledMenuItem>
          </a>
        )}
        {planRec && isElectron && (
          <StyledMenuItem
            id="helpSampleOff"
            onClick={handleDownload(sampleHref, isElectron)}
          >
            <ListItemIcon>
              <DownloadIcon />
            </ListItemIcon>
            <ListItemText primary={sampleDesc} />
          </StyledMenuItem>
        )}
        {planRec && isElectron && (
          <StyledMenuItem
            id="helpSampleGoogleOff"
            onClick={handleSite(API_CONFIG.googleSamples)}
          >
            <ListItemIcon>
              <FolderIcon />
            </ListItemIcon>
            <ListItemText primary={t.googleSamples} />
          </StyledMenuItem>
        )}
        {planRec && !isElectron && (
          <a
            href={API_CONFIG.googleSamples}
            style={{ textDecoration: 'none' }}
            target="_blank"
            rel="noopener noreferrer"
          >
            <StyledMenuItem id="helpOpenNotesOn">
              <ListItemIcon>
                <FolderIcon />
              </ListItemIcon>
              <ListItemText primary={t.googleSamples} />
            </StyledMenuItem>
          </a>
        )}
        {isElectron && (
          <StyledMenuItem
            id="helpOpenNotesOff"
            onClick={handleSite(API_CONFIG.openNotes)}
          >
            <ListItemIcon>
              <NotesIcon />
            </ListItemIcon>
            <ListItemText
              primary={t.brandedSite.replace('{0}', TranslatorsNotes)}
            />
          </StyledMenuItem>
        )}
        {!isElectron && (
          <a
            href={API_CONFIG.openNotes}
            style={{ textDecoration: 'none' }}
            target="_blank"
            rel="noopener noreferrer"
          >
            <StyledMenuItem id="helpOpenNotesOn">
              <ListItemIcon>
                <NotesIcon />
              </ListItemIcon>
              <ListItemText
                primary={t.brandedSite.replace('{0}', TranslatorsNotes)}
              />
            </StyledMenuItem>
          </a>
        )}
        {isElectron && (
          <StyledMenuItem
            id="helpResourcesOff"
            onClick={handleSite(API_CONFIG.resources)}
          >
            <ListItemIcon>
              <BooksIcon />
            </ListItemIcon>
            <ListItemText
              primary={t.brandedSite.replace('{0}', UbsResources)}
            />
          </StyledMenuItem>
        )}
        {!isElectron && (
          <a
            href={API_CONFIG.resources}
            style={{ textDecoration: 'none' }}
            target="_blank"
            rel="noopener noreferrer"
          >
            <StyledMenuItem id="helpResourcesOn">
              <ListItemIcon>
                <BooksIcon />
              </ListItemIcon>
              <ListItemText
                primary={t.brandedSite.replace('{0}', UbsResources)}
              />
            </StyledMenuItem>
          </a>
        )}
        {isElectron && (
          <StyledMenuItem
            id="helpOPenContentOff"
            onClick={handleSite(API_CONFIG.openContent)}
          >
            <ListItemIcon>
              <BooksIcon />
            </ListItemIcon>
            <ListItemText primary={t.openContent} />
          </StyledMenuItem>
        )}
        {!isElectron && (
          <a
            href={logosAppUri}
            style={{ textDecoration: 'none' }}
            target="_blank"
            rel="noopener noreferrer"
          >
            <StyledMenuItem id="helpLogosOn">
              <ListItemIcon>
                <LogosIcon />
              </ListItemIcon>
              <ListItemText primary={t.brandedSite.replace('{0}', Logos)} />
            </StyledMenuItem>
          </a>
        )}
        {isElectron && (
          <StyledMenuItem id="helpLogosOff" onClick={handleSite(logosAppUri)}>
            <ListItemIcon>
              <LogosIcon />
            </ListItemIcon>
            <ListItemText primary={t.brandedSite.replace('{0}', Logos)} />
          </StyledMenuItem>
        )}
        {!isElectron && (
          <a
            href={twInstallUri}
            style={{ textDecoration: 'none' }}
            target="_blank"
            rel="noopener noreferrer"
          >
            <StyledMenuItem id="helpLogosOn">
              <ListItemIcon>
                <TwIcon />
              </ListItemIcon>
              <ListItemText
                primary={t.brandedSite.replace('{0}', TranslatorsWorkplace)}
              />
            </StyledMenuItem>
          </a>
        )}
        {isElectron && (
          <StyledMenuItem id="helpLogosOff" onClick={handleSite(twInstallUri)}>
            <ListItemIcon>
              <TwIcon />
            </ListItemIcon>
            <ListItemText
              primary={t.brandedSite.replace('{0}', TranslatorsWorkplace)}
            />
          </StyledMenuItem>
        )}
        {!isElectron && (
          <a
            href={API_CONFIG.openContent}
            style={{ textDecoration: 'none' }}
            target="_blank"
            rel="noopener noreferrer"
          >
            <StyledMenuItem id="helpOpenContentkOn">
              <ListItemIcon>
                <BooksIcon />
              </ListItemIcon>
              <ListItemText primary={t.openContent} />
            </StyledMenuItem>
          </a>
        )}
        {isElectron && (
          <StyledMenuItem
            id="helpCourseOff"
            onClick={handleSite(API_CONFIG.course)}
          >
            <ListItemIcon>
              <TrainingIcon />
            </ListItemIcon>
            <ListItemText primary={t.course} />
          </StyledMenuItem>
        )}
        {!isElectron && (
          <a
            href={API_CONFIG.course}
            style={{ textDecoration: 'none' }}
            target="_blank"
            rel="noopener noreferrer"
          >
            <StyledMenuItem id="helpCourseOn">
              <ListItemIcon>
                <TrainingIcon />
              </ListItemIcon>
              <ListItemText primary={t.course} />
            </StyledMenuItem>
          </a>
        )}
        {isElectron && (
          <StyledMenuItem
            id="helpVideosOff"
            onClick={handleSite(API_CONFIG.videoTraining)}
          >
            <ListItemIcon>
              <TrainingIcon />
            </ListItemIcon>
            <ListItemText primary={t.videos} />
          </StyledMenuItem>
        )}
        {!isElectron && (
          <a
            href={API_CONFIG.videoTraining}
            style={{ textDecoration: 'none' }}
            target="_blank"
            rel="noopener noreferrer"
          >
            <StyledMenuItem id="helpVideosOn">
              <ListItemIcon>
                <TrainingIcon />
              </ListItemIcon>
              <ListItemText primary={t.videos} />
            </StyledMenuItem>
          </a>
        )}
        {isElectron && (
          <StyledMenuItem
            id="helpWalkThruOff"
            onClick={handleSite(API_CONFIG.walkThru)}
          >
            <ListItemIcon>
              <TrainingIcon />
            </ListItemIcon>
            <ListItemText primary={t.walkThru} />
          </StyledMenuItem>
        )}
        {!isElectron && (
          <a
            href={API_CONFIG.walkThru}
            style={{ textDecoration: 'none' }}
            target="_blank"
            rel="noopener noreferrer"
          >
            <StyledMenuItem id="helpWalkThruOn">
              <ListItemIcon>
                <TrainingIcon />
              </ListItemIcon>
              <ListItemText primary={t.walkThru} />
            </StyledMenuItem>
          </a>
        )}
        {isElectron && (
          <StyledMenuItem
            id="helpAkuoOff"
            onClick={handleSite(API_CONFIG.akuo)}
          >
            <ListItemIcon>
              <AkuoLogo />
            </ListItemIcon>
            <ListItemText primary={t.brandedSite.replace('{0}', Akuo)} />
          </StyledMenuItem>
        )}
        {!isElectron && (
          <a
            href={API_CONFIG.akuo}
            style={{ textDecoration: 'none' }}
            target="_blank"
            rel="noopener noreferrer"
          >
            <StyledMenuItem id="helpAkuoOn">
              <ListItemIcon>
                <AkuoLogo />
              </ListItemIcon>
              <ListItemText primary={t.brandedSite.replace('{0}', Akuo)} />
            </StyledMenuItem>
          </a>
        )}
        {shift && (
          <StyledMenuItem id="helpDevMode" onClick={handleDeveloper}>
            <ListItemIcon>
              {developer ? <RemoveIcon /> : <AddIcon />}
            </ListItemIcon>
            <ListItemText primary={t.developer} />
          </StyledMenuItem>
        )}
        {isElectron && (
          <StyledMenuItem
            id="helpFeedbackOff"
            onClick={handleSite(API_CONFIG.community)}
          >
            <ListItemIcon>
              <ReportIcon />
            </ListItemIcon>
            <ListItemText primary={t.reportIssue} />
          </StyledMenuItem>
        )}
        {!isElectron && (
          <a
            href={API_CONFIG.community}
            style={{ textDecoration: 'none' }}
            target="_blank"
            rel="noopener noreferrer"
          >
            <StyledMenuItem id="helpFeedbackOn">
              <ListItemIcon>
                <ReportIcon />
              </ListItemIcon>
              <ListItemText primary={t.reportIssue} />
            </StyledMenuItem>
          </a>
        )}
        <StyledMenuItem id="helpAbout" onClick={handleAbout(true)}>
          <ListItemIcon>
            <InfoIcon />
          </ListItemIcon>
          <ListItemText primary={t.about} />
        </StyledMenuItem>
      </StyledMenu>
      <ContextHelp topic={topic} reset={handleReset} />
      <AboutDialog open={aboutOpen} onClose={handleAbout(false)} />
    </div>
  );
}

export default HelpMenu;

// eslint-disable-next-line @typescript-eslint/no-unused-vars
import React from 'react';
// See: https://www.w3schools.com/TAGS/ref_av_dom.asp
import { cleanup, render, waitFor } from '@testing-library/react';
import { MediaPlayer } from './MediaPlayer';
import { act } from 'react';
import { HiddenPlayerProps } from './HiddenPlayer';

enum MediaSt {
  IDLE,
  PENDING,
  FETCHED,
  ERROR,
}
interface IMediaState {
  status: MediaSt;
  error: null | string;
  url: string; // temporary url
  id: string; // media id
  remoteId: string;
  cancelled: boolean;
}

enum BlobStatus {
  IDLE,
  PENDING,
  RESET,
  FETCHED,
  ERROR,
}

interface IBlobState extends IMediaState {
  blob: Blob;
  blobStat: BlobStatus;
}

const mediaClean = {
  status: MediaSt.IDLE,
  error: null,
  url: '',
  id: '',
  remoteId: '',
  cancelled: false,
};
const mockBlobClean = {
  ...mediaClean,
  blob: new Blob(),
  blobStat: BlobStatus.IDLE,
};
let mockMediaState: IMediaState = { ...mediaClean };
let mockBlobState: IBlobState = { ...mockBlobClean };
const mockFetchBlob = jest.fn();
const mockShowMessage = jest.fn();
let mockShouldUseWaveSurfer = false;

jest.mock('../utils/audioPlayback', () => ({
  shouldUseWaveSurferPlayback: jest.fn(() => mockShouldUseWaveSurfer),
}));

jest.mock('./HiddenPlayer', () => {
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const MockHiddenPlayer = (_props: HiddenPlayerProps) => {
    return <div id="hiddenplayer" />;
  };
  MockHiddenPlayer.displayName = 'MockHiddenPlayer';
  return MockHiddenPlayer;
});

jest.mock('../crud/useFetchMediaBlob', () => {
  const BlobStatus = {
    IDLE: 0,
    PENDING: 1,
    RESET: 2,
    FETCHED: 3,
    ERROR: 4,
  };
  return {
    useFetchMediaBlob: () => [mockBlobState, mockFetchBlob],
    BlobStatus,
  };
});

jest.mock('../crud', () => {
  const MediaSt = {
    IDLE: 0,
    PENDING: 1,
    FETCHED: 2,
    ERROR: 3,
  };
  return {
    useFetchMediaUrl: () => {
      return {
        mediaState: mockMediaState,
        fetchMediaUrl: ({ id }: { id: string }) => {
          if (id === '1') {
            mockMediaState = {
              ...mockMediaState,
              id: 'abcd-1',
              remoteId: '1',
              error: '',
              status: MediaSt.PENDING,
            };
            setTimeout(() => {
              mockMediaState = {
                ...mockMediaState,
                status: MediaSt.FETCHED,
                url: 'https://localhost/media/1.mp3',
              };
            }, 500);
          } else if (id === 'ogg-1') {
            mockMediaState = {
              ...mockMediaState,
              id: 'abcd-ogg',
              remoteId: 'ogg-1',
              error: '',
              status: MediaSt.FETCHED,
              url: 'https://localhost/media/1.ogg',
            };
          } else {
            mockMediaState = { ...mockMediaState, error: 'error' };
          }
        },
      };
    },
    MediaSt,
  };
});

jest.mock('../hoc/SnackBar', () => ({
  useSnackBar: () => ({
    showMessage: mockShowMessage,
  }),
}));

jest.mock('../selector', () => ({
  peerCheckSelector: jest.fn(),
  sharedSelector: jest.fn(),
}));

jest.mock('react-redux', () => ({
  useSelector: () => ({
    afterResource: 'Play from end of resource',
    back3Seconds: 'Skip back 3 seconds',
    resourceStart: 'Play from start of resource',
    mediaError: 'Media error',
    fileNotFound: 'File not found',
    close: 'Close',
  }),
  shallowEqual: jest.fn(),
}));

jest.mock('../context/useGlobal', () => ({
  useGlobal: (key: string) => {
    const mockValues: Record<string, unknown> = {
