interface IProps {
  inItem?: string;
  label?: string;
  onChange?: (resource: string, latest: boolean) => void;
  required?: boolean;
  tags: string[];
  latestVernacular: number;
}
export const SelectRecording = (props: IProps) => {
  const { onChange, inItem, tags, latestVernacular } = props;
  const lang = useSelector((state: IState) => state.strings.lang);
  const ctx = useContext(PassageDetailContext);
  const { rowData } = ctx.state;
  const [item, setItem] = useState('');
  const [chooser, setChooser] = useState(false);
  const { localizedArtifactType } = useArtifactType();
  const t: ISelectRecordingStrings = useSelector(
    selectRecordingSelector,
    shallowEqual
  );

  const showTopic = useMemo(() => {
    return (
      tags[0] !== ArtifactTypeSlug.WholeBackTranslation &&
      tags[0] !== ArtifactTypeSlug.PhraseBackTranslation
    );
  }, [tags]);

  const showType = useMemo(() => {
    return tags.length > 1;
  }, [tags]);

  const handleClick = (id: string, latest: boolean) => () => {
    setItem(id);
    onChange && onChange(id, latest);
    setChooser(false);
  };

  const handleItem = () => {
    setChooser(true);
  };

  useEffect(() => {
    if (inItem) setItem(inItem);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [inItem]);

  const localTags = useMemo(() => {
    return tags.map((t) => localizedArtifactType(t));
  }, [tags, localizedArtifactType]);
  return (
    <>
      <Box sx={{ display: 'flex', alignItems: 'center' }}>
        <Button id="select-recording" onClick={handleItem} variant="contained">
          {t.playItem}
        </Button>
        <ItemDescription
          mediafile={rowData.find((r) => r.id === item)?.mediafile}
        />
      </Box>
      {chooser && (
        <BigDialog
          title={t.selectRecording}
          isOpen={chooser}
          onOpen={setChooser}
        >
          <TableContainer component={Paper}>
            <Table size="small" aria-label="a dense table">
              <TableHead>
                <RecordingHeader showTopic={showTopic} showType={showType} />
              </TableHead>
              <TableBody>
                {rowData
                  .filter((r) => localTags.includes(r.artifactType))
                  .sort((i, j) =>
                    parseFloat(
                      prettySegment(
                        i?.mediafile?.attributes?.sourceSegments ?? '{}'
                      )
                    ) <
                    parseFloat(
                      prettySegment(
                        j?.mediafile?.attributes?.sourceSegments ?? '{}'
                      )
                    )
                      ? -1
                      : parseFloat(
                            prettySegment(
                              i?.mediafile?.attributes?.sourceSegments ?? '{}'
                            )
                          ) >
                          parseFloat(
                            prettySegment(
                              j?.mediafile?.attributes?.sourceSegments ?? '{}'
                            )
                          )
                        ? 1
                        : i.artifactType < j.artifactType
                          ? -1
                          : i.artifactType > j.artifactType
                            ? 1
                            : i.sourceVersion === j.sourceVersion
                              ? i.artifactName <= j.artifactName
                                ? -1
                                : 1
                              : j.sourceVersion - i.sourceVersion
                  )
                  .map((r) => (
                    <RecordingInfo
                      key={r.id}
                      row={r}
                      lang={lang}
                      onClick={handleClick}
                      latestVernacular={latestVernacular}
                      showTopic={showTopic}
                      showType={showType}
                    />
                  ))}
              </TableBody>
            </Table>
          </TableContainer>
        </BigDialog>
      )}
    </>
  );
};
export default SelectRecording;

import { Box, debounce, useTheme } from '@mui/material';
import { Stage } from '../../control/Stage';
import usePassageDetailContext from '../../context/usePassageDetailContext';
import { useEffect, useState } from 'react';
import { SimpleWf } from '../../context/PassageDetailContext';
import { useGetGlobal } from '../../context/useGlobal';
import { useSnackBar } from '../../hoc/SnackBar';
import { shallowEqual, useSelector } from 'react-redux';
import { sharedSelector } from '../../selector';
import { useWfLabel } from '../../utils/useWfLabel';

export function WorkflowSteps() {
  const {
    workflow,
    stepComplete,
    currentstep,
    setCurrentStep,
    firstStepIndex,
    setFirstStepIndex,
    recording,
    commentRecording,
  } = usePassageDetailContext();
  const theme = useTheme();
  const [shownWorkflow, setShownWorkflow] = useState<SimpleWf[]>([]);
  const [width, setWidth] = useState(0);
  const [stageWdith, setStageWidth] = useState(300);
  const { showMessage } = useSnackBar();
  const ts = useSelector(sharedSelector, shallowEqual);
  const getWfLabel = useWfLabel();
  const getGlobal = useGetGlobal();
  const prevWF = {
    id: 'prev',
    label: '<<',
  };
  const nextWF = {
    id: 'next',
    label: '>>',
  };

  // keep track of screen width
  const setDimensions = () => {
    setWidth(window.innerWidth);
  };

  useEffect(() => {
    setDimensions();
    const handleResize = debounce(() => {
      setDimensions();
    }, 100);

    window.addEventListener('resize', handleResize);
    return () => {
      window.removeEventListener('resize', handleResize);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []); //do this once to get the default;

  useEffect(() => {
    const show = Math.ceil(width / 200);
    // 24 for next/prev icon + 16 padding with 10 padding on bar = 100
    const newStageWdith = (width - 100) / show;
    if (newStageWdith !== stageWdith) setStageWidth(newStageWdith);
    if (!workflow || !workflow.length) return;
    let tempFirstStep = firstStepIndex;
    if (firstStepIndex < 0) {
      if (currentstep) {
        const stepIndex = workflow.findIndex((w) => w.id === currentstep);
        tempFirstStep = Math.floor(Math.max(stepIndex - show / 2, 0));
      } else tempFirstStep = 0;
      setFirstStepIndex(tempFirstStep);
    }
    let wf: SimpleWf[] = [];
    wf.push({ ...prevWF, label: tempFirstStep > 0 ? prevWF.label : '' });
    wf = wf.concat(workflow.slice(tempFirstStep, tempFirstStep + show));
    wf.push({
      ...nextWF,
      label: tempFirstStep + show < workflow.length ? nextWF.label : '',
    });
    setShownWorkflow(wf);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentstep, firstStepIndex, workflow, width]);

  const curColor = (id: string) => {
    return id === currentstep
      ? theme.palette.secondary.light
      : stepComplete(id)
        ? theme.palette.grey[300]
        : undefined;
  };

  const handleSelect = (item: string) => {
    if (recording || commentRecording) return;
    if (getGlobal('remoteBusy')) {
      showMessage(ts.wait);
      return;
    }
    if (item === currentstep) {
      //do nothing;
    } else {
      setCurrentStep(item);
    }
  };
  const moveStep = (forward: boolean) => {
    if (forward)
      setFirstStepIndex(Math.min(workflow.length - 1, firstStepIndex + 1));
    else setFirstStepIndex(Math.max(0, firstStepIndex - 1));
  };
  return (
    <Box sx={{ display: 'flex', alignItems: 'center' }}>
      {shownWorkflow.map((w) => (
        <Stage
          key={w.id}
          id={w.id}
          disabled={recording || commentRecording}
          label={getWfLabel(w.label)}
          color={curColor(w.id)}
          textColor={
            w.id === currentstep
              ? theme.palette.secondary.contrastText
              : recording || commentRecording
                ? '#d3d3d3'
                : '#000000'
          }
          wid={stageWdith}
          done={stepComplete(w.id)}
          select={handleSelect}
          moveStep={moveStep}
        />
      ))}
    </Box>
  );
}

