  const ts: ISharedStrings = useSelector(sharedSelector, shallowEqual);
  useWhyRender('UserMenu', {
    users,
    user,
    org,
    orgRole,
    isBoldWorkflow,
    userIsAdmin,
    addStoryOrPassage,
    anchorEl,
    userRec,
    t,
    ts,
  });

  const handleClick = (event: React.MouseEvent<HTMLElement>) => {
    setShift(event.shiftKey);
    setAnchorEl(event.currentTarget);
  };

  const handleProfile = (visible: boolean) => () => {
    if (visible !== profileOpen) setProfileOpen(visible);
    restoreScroll();
    setAnchorEl(null);
  };

  useEffect(() => {
    const userRecs = users.filter((u) => u.id === user) as UserD[];
    const newRec = userRecs.length > 0 ? userRecs[0] : undefined;
    if (userRec !== newRec) {
      setUserRec(newRec);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user, users, userRec]);

  const handleAction = (what: string) => () => {
    setAnchorEl(null);
    if (action) action(what);
  };

  const handleMobileViewToggle = () => {
    const newValue = !isMobileView;
    setMobileView(newValue);
    localStorage.setItem(localUserKey(LocalKey.mobileView), String(newValue));
    setAnchorEl(null);
  };

  const handleAddStoryOrPassageToggle = () => {
