          <ListItemText primary={t.myAccount} />
        </StyledMenuItem>
        {!isMobileWidth && isDeveloper && (
          <StyledMenuItem id="mobileView" onClick={handleMobileViewToggle}>
            <ListItemIcon>
              <Checkbox
                checked={isMobileView}
                size="small"
                sx={{ padding: 0 }}
              />
            </ListItemIcon>
            <ListItemText primary={t.mobileView} />
