  oldVernacularPlaying: false,
  handleOldVernacularPlayEnd: () => {},
  rowData: Array<IRow>(),

  loading: false,
  audioBlob: undefined as Blob | undefined,
  pdBusy: false,
  setPDBusy: (_pdBusy: boolean) => {},
  allBookData: Array<BookName>(),
  workflow: Array<SimpleWf>(),
  psgCompleted: [] as StepComplete[],
  setStepComplete: async (
    _stepId: string,
    _complete: boolean,
    _psgCompleted?: StepComplete[]
  ): Promise<void> => {},
  setStepCompleteTo: async (_stepId: string) => {},
  gotoNextStep: () => {},
  stepComplete: (_stepId: string) => {
    return false;
  },
  discussionSize: { width: 450, height: 900 },
  setDiscussionSize: (_size: { width: number; height: number }) => {},
  chooserSize: 48,
  setChooserSize: (_size: number) => {},
  defaultFilename: '',
  uploadItem: '',
  currentSegment: '',
  currentSegmentIndex: -1,
  /**
   * Increments on every actual change of the current segment.
   *
   * `currentSegmentIndex` cannot be used to notice a change, because its
   * numbering is not agreed: the waveform writes a 1-based sorted position
   * (0 meaning "whole") via usePlayerLogic, Mark Verses writes a table row, and
   * PassageDetailGuidedPhraseRecord writes a 0-based clause index. A real move
   * can therefore arrive carrying the number the previous writer used — e.g.
   * selecting segment 2 (waveform: 1+1) right after the step selected segment 3
   * (step: 2) — and an effect watching the index alone never re-runs.
   *
   * Watch this instead when you only need to know that the selection moved.
   */
  currentSegmentSeq: 0,
  setCurrentSegment: (_segment: IRegion | undefined, index: number) => {}, //replace the above two
  setupLocate: (cb?: (segments: string) => void) => {},
  getCurrentSegment: () => undefined as IRegion | undefined,
  setPlayerSegments: (_segments: string) => {},
  recording: false,
  setRecording: (_recording: boolean) => {},
  commentRecording: false,
  setCommentRecording: (_commentRecording: boolean) => {},
  isNavigationBlocked: () => false,
  handleItemPlayEnd: () => {},
  handleItemTogglePlay: () => {},
  handleCommentPlayEnd: () => {},
  handleCommentTogglePlay: () => {},
  discussionMarkers: [] as IMarker[],
  setDiscussionMarkers: (_markers: IMarker[]) => {},
  handleHighlightDiscussion: (_time: number | undefined) => {},
  highlightDiscussion: undefined as number | undefined,
  refresh: 0,
  prjId: '',
  forceRefresh: (_rowData?: IRow[]) => {},
  sectionArr: [] as SectionArray,
  toggleDone: (_id: string) => {},
  canPublish: false,
  discussOpen: false,
  setDiscussOpen: (_discussOpen: boolean) => {},
  isBoldWorkflow: false,
  promptPlaybackComplete: false,
  setPromptPlaybackComplete: (_complete: boolean) => {},
  promptDockedRecordButton: null as React.ReactNode | null,
  setPromptDockedRecordButton: (_node: React.ReactNode | null) => {},
  promptDockedRecordFooterVersion: 0,
  carefulSpeechSegParams: boldDefaultSegParams,
  setCarefulSpeechSegParams: (_params: IRegionParams) => {},
  hideMobileHeader: false,
  setHideMobileHeader: (_hide: boolean) => {},
};

export type ICtxState = typeof initState;

interface IContext {
  state: ICtxState;
  setState: React.Dispatch<React.SetStateAction<ICtxState>>;
}

const PassageDetailContext = React.createContext({
  state: initState as ICtxState,
  setState: () => {},
} as IContext);

interface IProps {
  children: React.ReactElement;
}
const PassageDetailProvider = (props: IProps) => {
  useRenderProfiler('PassageDetailProvider');
  const passages = useOrbitData<Passage[]>('passage');
  const sections = useOrbitData<Section[]>('section');
  const mediafiles = useOrbitData<MediaFileD[]>('mediafile');
  const artifactTypes = useOrbitData<ArtifactType[]>('artifacttype');
  const categories = useOrbitData<ArtifactCategory[]>('artifactcategory');
  const userResources = useOrbitData<SectionResourceUser[]>(
    'sectionresourceuser'
  );
  const sectionResources = useOrbitData<SectionResourceD[]>('sectionresource');
  const wfStr: IWorkflowStepsStrings = useSelector(
    workflowStepsSelector,
    shallowEqual
  );
  const sharedStr: ISharedStrings = useSelector(sharedSelector, shallowEqual);
  const stepCompleteStr: IPassageDetailStepCompleteStrings = useSelector(
    passageDetailStepCompleteSelector,
    shallowEqual
  );
  const lang = useSelector((state: IState) => state.strings.lang);
  const allBookData = useSelector((state: IState) => state.books.bookData);
  const booksLoaded = useSelector((state: IState) => state.books.loaded);
  const dispatch = useDispatch();
  const fetchBooks = (lang: string) =>
    dispatch(actions.fetchBooks(lang) as any);
  const { pasId, prjId } = useParams();
  const [memory] = useGlobal('memory');
  const [user] = useGlobal('user');
  const [org] = useGlobal('organization');
  const [errorReporter] = useGlobal('errorReporter');
  const [saveResult, setSaveResult] = useGlobal('saveResult'); //verified this is not used in a function 2/18/25
  const [confirm, setConfirm] = useState('');
  const [incompleteNavTarget, setIncompleteNavTarget] = useState('');
  const view = React.useRef('');
  const { showMessage } = useSnackBar();
  const [plan] = useGlobal('plan'); //will be constant here
  const { getProjectDefault } = useProjectDefaults();
  const [state, setState] = useState({
    ...initState,
    allBookData,
    prjId: prjId ?? '',
  });
  const [blobState, fetchBlob] = useFetchMediaBlob();
  const fetching = useRef('');
  const segmentsCb = useRef<((segments: string) => void) | undefined>(
    undefined
  );
  const filteredOrgSteps = useFilteredSteps();
  const { localizedArtifactType, getTypeId } = useArtifactType();
  const { localizedArtifactCategory } = useArtifactCategory();
  const { localizedWorkStep } = useOrgWorkflowSteps();
  const mediaStart = useRef<number | undefined>(undefined);
  const mediaEnd = useRef<number | undefined>(undefined);
  const mediaPosition = useRef<number | undefined>(undefined);
  const currentSegmentRef = useRef<IRegion | undefined>(undefined);
  const currentSegmentIndexRef = useRef(-1);
  /** Change token for the current segment; see initState.currentSegmentSeq. */
  const currentSegmentSeqRef = useRef(0);
  const { startSave, startClear, waitForSave, forceClearPending } =
    useContext(UnsavedContext).state;
  const highlightRef = useRef<number | undefined>(undefined);
  const refreshRef = useRef<number>(0);
  const recordingRef = useRef(false);
  const commentRecordingRef = useRef(false);
  const settingSegmentRef = useRef(false);
  const inPlayerRef = useRef<string | undefined>(undefined);
  const { getOrgDefault } = useOrgDefaults();
  const getGlobal = useGetGlobal();
  const { canPublish } = useProjectPermissions();
  const teamWorkflowProcess = useTeamWorkflowProcess(org);
  const isBoldWorkflow = teamWorkflowProcess === BOLD_WORKFLOW_PROCESS;

  const stepComplete = (stepid: string) => {
    stepid =
      remoteId('orgworkflowstep', stepid, memory?.keyMap as RecordKeyMap) ||
      stepid;
    const step = state.psgCompleted.find((s) => s.stepid === stepid);
    return Boolean(step?.complete);
  };

  const isNavigationBlocked = () =>
    isPassageNavigationBlocked(
      recordingRef.current,
      commentRecordingRef.current
    );

  const handleSetCurrentStep = (stepId: string) => {
    const step = state.orgWorkflowSteps.find((s) => s.id === stepId);
    const tool = getTool(step?.attributes?.tool) as ToolSlug;
    setCurrentSegment(undefined, 0);
    // Clear discussion locate without handleHighlightDiscussion — that helper
    // no-ops while settingSegmentRef is set (mid-locate/play), which is exactly
    // when step switches hang after the compass button.
    highlightRef.current = undefined;
    settingSegmentRef.current = false;

    setState((state: ICtxState) => {
      return {
        ...state,
        currentstep: stepId,
        tool,
        playing: false,
        itemPlaying: false,
        commentPlaying: false,
        oldVernacularPlaying: false,
        playItem: '',
        commentPlayId: '',
        oldVernacularPlayItem: '',
        highlightDiscussion: undefined,
      };
    });

    if (step && tool !== ToolSlug.Resource && tool !== ToolSlug.Transcribe) {
      //this does a bunch of stuff...don't just set it in the state above...
      if (
        state.rowData.length > 0 &&
        state.rowData[0] !== undefined &&
        state.rowData[0].isVernacular
      ) {
        setSelected(state.rowData[0].id, PlayInPlayer.yes);
      } else setSelected('', PlayInPlayer.yes);
    }
    segmentsCb.current = undefined;
  };

  const attemptSetCurrentStep = (stepId: string) => {
    if (isNavigationBlocked()) return;
    if (needsStepNavigationConfirm(state.currentstep, stepId, stepComplete)) {
      setIncompleteNavTarget(stepId);
      return;
    }
    handleSetCurrentStep(stepId);
  };

  const setCurrentStep = (stepId: string) => {
    if (isNavigationBlocked()) return;
    if (getGlobal('changed')) {
      setConfirm(stepId);
    } else {
      attemptSetCurrentStep(stepId);
    }
  };

  const passageNavigate = usePassageNavigate(
    () => {},
    setCurrentStep,
    isNavigationBlocked
  );

  const forceRefresh = (rowData?: IRow[]) => {
    refreshRef.current = refreshRef.current + 1;
    setState((state: ICtxState) => {
      return {
        ...state,
        refresh: refreshRef.current,
        rowData: rowData ?? state.rowData,
      };
    });
  };

  const setFirstStepIndex = (stepIndex: number) => {
    setState((state: ICtxState) => {
      return {
        ...state,
        firstStepIndex: stepIndex,
      };
    });
  };

  const finishStepConfirm = (target: string) => {
    try {
      attemptSetCurrentStep(target);
    } finally {
      setConfirm('');
    }
  };

  const handleConfirmStep = () => {
    const target = confirm;
    startSave();
    // Do not pass finishStepConfirm into waitForSave — its blanket catch turns
    // callback throws into 'Timed Out' and would re-run navigation below.
    void waitForSave(undefined, 400).then(
      () => finishStepConfirm(target),
      (err) => {
        showMessage(err?.message || String(err));
        setConfirm('');
      }
    );
  };

  const handleRefuseStep = () => {
    const target = confirm;
    // forceClearPending on wait failure for orphaned tools (unmounted after mid-play step switch).
    startClear();
    void waitForSave(undefined, 15).then(
      () => finishStepConfirm(target),
      (err) => {
        showMessage(err?.message || String(err));
        forceClearPending();
        finishStepConfirm(target);
      }
    );
  };

  const setDiscussionSize = (discussionSize: {
    width: number;
    height: number;
  }) => {
    setState((state: ICtxState) => {
      return { ...state, discussionSize };
    });
  };

  const setChooserSize = (chooserSize: number) => {
    setState((state: ICtxState) => {
      return { ...state, chooserSize };
    });
  };

  const setDiscussOpen = useCallback((discussOpen: boolean) => {
    setState((state: ICtxState) => {
      if (state.discussOpen === discussOpen) {
        return state;
      }
      return { ...state, discussOpen };
    });
  }, []);

  const setHideMobileHeader = useCallback((hideMobileHeader: boolean) => {
    setState((state: ICtxState) => {
      if (state.hideMobileHeader === hideMobileHeader) {
        return state;
      }
      return { ...state, hideMobileHeader };
    });
  }, []);

  const setPromptPlaybackComplete = useCallback(
    (promptPlaybackComplete: boolean) => {
      setState((state: ICtxState) => {
        if (state.promptPlaybackComplete === promptPlaybackComplete) {
          return state;
        }
        return { ...state, promptPlaybackComplete };
      });
    },
    []
  );

  const promptDockedRecordButtonRef = useRef<React.ReactNode | null>(null);
  const [promptDockedRecordFooterVersion, setPromptDockedRecordFooterVersion] =
    useState(0);

  const setPromptDockedRecordButton = useCallback(
    (node: React.ReactNode | null) => {
      promptDockedRecordButtonRef.current = node;
      setPromptDockedRecordFooterVersion((v) => v + 1);
    },
    []
  );

  const setRecording = (recording: boolean) => {
    recordingRef.current = recording;
    setState((state: ICtxState) => {
      return {
        ...state,
        playing: false, //stop the vernacular
        itemPlaying: false,
        commentPlaying: false,
        oldVernacularPlaying: false,
        recording,
      };
    });
  };
  const setCommentRecording = (commentRecording: boolean) => {
    commentRecordingRef.current = commentRecording;
    setState((state: ICtxState) => {
      return {
        ...state,
        playing: false, //stop the vernacular
        itemPlaying: false,
        commentPlaying: false,
        oldVernacularPlaying: false,
        commentRecording,
      };
    });
  };

  //this is for the PD Player only
  const setPlaying = (playing: boolean) => {
    //if this is called from a callback, we don't know the state
    //if (playing !== state.playing) {
    if (playing)
      setState((state: ICtxState) => {
        return {
          ...state,
          playing,
          itemPlaying: false,
          commentPlaying: false,
          oldVernacularPlaying: false,
          oldVernacularPlayItem: '',
          oldVernacularStart: 0,
        };
      });
    else
      setState((state: ICtxState) => {
        if (!state.playing) return state;
        return {
          ...state,
          playing,
        };
      });
  };
  const setItemPlaying = (itemPlaying: boolean) => {
    if (itemPlaying !== state.itemPlaying) {
      setState((state: ICtxState) => {
        return {
          ...state,
          itemPlaying,
          playing: itemPlaying ? false : state.playing,
          commentPlaying: itemPlaying ? false : state.commentPlaying,
          oldVernacularPlaying: itemPlaying
            ? false
            : state.oldVernacularPlaying,
          oldVernacularPlayItem: itemPlaying ? '' : state.oldVernacularPlayItem,
          oldVernacularStart: itemPlaying ? 0 : state.oldVernacularStart,
        };
      });
    }
  };
  const setCommentPlaying = (
    commentPlaying: boolean,
    ended: boolean = false
  ) => {
    if (commentPlaying !== state.commentPlaying) {
      setState((state: ICtxState) => {
        return {
          ...state,
          commentPlaying,
          commentPlayId: ended ? '' : state.commentPlayId,
          playing: commentPlaying ? false : state.playing,
          itemPlaying: commentPlaying ? false : state.itemPlaying,
          oldVernacularPlaying: commentPlaying
            ? false
            : state.oldVernacularPlaying,
          oldVernacularPlayItem: commentPlaying
            ? ''
            : state.oldVernacularPlayItem,
        };
      });
    }
  };

  const handleItemPlayEnd = () => {
    setItemPlaying(false);
    oldVernReset();
  };
  const handleItemTogglePlay = () => {
    setItemPlaying(!state.itemPlaying);
  };
  const handleCommentPlayEnd = () => {
    if (state.commentPlaying) setCommentPlaying(false, true);
    else setCommentPlayId('');
  };

  const handleCommentTogglePlay = () => {
    setCommentPlaying(!state.commentPlaying);
  };
  const handleOldVernacularPlayEnd = () => {
    mediaStart.current = undefined;
    mediaEnd.current = undefined;
    setState((state: ICtxState) => {
      return {
        ...state,
        oldVernacularPlaying: false,
        oldVernacularPlayItem: '',
        oldVernacularStart: 0,
      };
    });
  };
  const setPDBusy = (busy: boolean) => {
    setState((state: ICtxState) => {
      return {
        ...state,
        pdBusy: busy,
      };
    });
  };

  const setCarefulSpeechSegParams = (params: IRegionParams) => {
    setState((state: ICtxState) => {
      return { ...state, carefulSpeechSegParams: params };
    });
  };

  const setDiscussionMarkers = (discussionMarkers: IMarker[]) => {
    setState((state: ICtxState) => {
      return { ...state, discussionMarkers };
    });
  };
  const handleHighlightDiscussion = (time: number | undefined) => {
    if (settingSegmentRef.current) return;

    settingSegmentRef.current = true;
    if (highlightRef.current !== time) {
      highlightRef.current = time;
      setState((state: ICtxState) => {
        return {
          ...state,
          highlightDiscussion: time,
        };
      });
    } else if (time !== undefined) {
      //force refresh if they've hit the same locate button again
      refreshRef.current = refreshRef.current + 1;
      setState((state: ICtxState) => {
        return { ...state, refresh: refreshRef.current, playing: false };
      });
    } else settingSegmentRef.current = false;
  };

  const gotoNextStep = () => {
    const gotoNextPassage =
      !isBoldWorkflow &&
      getOrgDefault(orgDefaultWorkflowProgression) !== WorkflowProgression.Step;
    const nextpsg = gotoNextPassage
      ? nextPasId(state.section, state.passage.id, memory)
      : undefined;
    if (nextpsg && nextpsg !== state.passage?.keys?.remoteId) {
      rememberCurrentPassage(memory, nextpsg);
      passageNavigate(`/detail/${prjId}/${nextpsg}`);
    } else {
      setCurrentStep('');
    } // setting to empty jumps to first uncompleted
  };
  const setStepComplete = async (
    stepid: string,
    complete: boolean,
    psgCompleted?: StepComplete[]
  ) => {
    if (stepid === '') return;
    const completed = psgCompleted ?? [...state.psgCompleted];
    const remId =
      remoteId('orgworkflowstep', stepid, memory?.keyMap as RecordKeyMap) ||
      stepid;
    const step = completed.find((s) => s.stepid === remId);
    const rec = findRecord(
      memory,
      'orgworkflowstep',
      stepid
    ) as OrgWorkflowStep;
    if (step) {
      step.complete = complete;
    } else {
      completed.push({ stepid: remId, complete, name: rec.attributes.name });
    }
    const recId = {
      type: 'passage',
      id:
        remoteIdGuid('passage', pasId ?? '', memory?.keyMap as RecordKeyMap) ||
        pasId ||
        '',
    };
    const curPassage = findRecord(memory, 'passage', recId.id) as Passage;
    const curCompleteStr = curPassage?.attributes.stepComplete;
    let stepComplete = {};
    try {
      stepComplete = JSON.parse(curCompleteStr || '{}');
    } catch (err) {
      logError(
        Severity.error,
        errorReporter,
        infoMsg(err as Error, 'Json conversion error')
      );
    }
    const tb = new RecordTransformBuilder();
    const ops = [] as RecordOperation[];
    ops.push(
      tb
        .replaceAttribute(
          recId,
          'stepComplete',
          JSON.stringify({ ...stepComplete, completed })
        )
        .toOperation()
    );
    ops.push(...UpdateLastModifiedBy(tb, recId, user));
    AddPassageStateChangeToOps(
      tb,
      ops,
      recId.id,
      '',
      `${
        complete ? stepCompleteStr.title : stepCompleteStr.incomplete
      } : ${localizedWorkStep(rec.attributes.name)}`,
      user,
      memory
    );
    await memory.update(ops);
    setState((state: ICtxState) => ({ ...state, psgCompleted: completed }));
  };
  const setStepCompleteTo = async (stepid: string) => {
    if (stepid === '') return;
    const completed: StepComplete[] = [];
    const steps = state.orgWorkflowSteps.sort(
      (a, b) => a.attributes.sequencenum - b.attributes.sequencenum
    );
    let rec;
    for (const step of steps) {
      const remId =
        remoteId('orgworkflowstep', step.id, memory.keyMap as RecordKeyMap) ||
        step.id;
      rec = findRecord(memory, 'orgworkflowstep', step.id) as OrgWorkflowStep;
      completed.push({
        stepid: remId,
        complete: true,
        name: rec.attributes.name,
      });
      if (step.id === stepid) break;
    }
    const recId = {
      type: 'passage',
      id:
        remoteIdGuid('passage', pasId ?? '', memory.keyMap as RecordKeyMap) ||
        pasId ||
        '',
    };
    const tb = new RecordTransformBuilder();
    const ops = [] as RecordOperation[];
    ops.push(
      tb
        .replaceAttribute(recId, 'stepComplete', JSON.stringify({ completed }))
        .toOperation()
    );
    ops.push(...UpdateLastModifiedBy(tb, recId, user));
    AddPassageStateChangeToOps(
      tb,
      ops,
      recId.id,
      '',
      `${stepCompleteStr.title} : ${localizedWorkStep(
        rec?.attributes?.name ?? ''
      )}`,
      user,
      memory
    );
    await memory.update(ops);
    setState((state: ICtxState) => ({ ...state, psgCompleted: completed }));
  };

  const handleIncompleteNavCancel = () => {
    setIncompleteNavTarget('');
  };

  const handleIncompleteNavContinue = () => {
    if (isNavigationBlocked()) return;
    const target = incompleteNavTarget;
    setIncompleteNavTarget('');
    if (target) handleSetCurrentStep(target);
  };

  const handleIncompleteNavComplete = () => {
    if (isNavigationBlocked()) return;
    const target = incompleteNavTarget;
    const fromStep = state.currentstep;
    setIncompleteNavTarget('');
    if (!target || !fromStep) return;
    void waitForSave(async () => {
      await setStepComplete(fromStep, true);
      handleSetCurrentStep(target);
    }, 200);
  };

  const incompleteNavMessage = (() => {
    if (!incompleteNavTarget) return '';
    const step = state.orgWorkflowSteps.find((s) => s.id === state.currentstep);
    const label = step
      ? localizedWorkStep(step.attributes.name)
      : state.currentstep;
    return wfStr.incompleteStepNavigate.replace('{0}', label);
  })();

  const getProjectResources = () => {
    const typeId = getTypeId(ArtifactTypeSlug.ProjectResource);
    return mediafiles.filter(
      (m) =>
        related(m, 'plan') === plan && related(m, 'artifactType') === typeId
    );
  };

  const setSelected = (
    selected: string,
    inPlayer: PlayInPlayer,
    rowData: IRow[] = state.rowData
  ) => {
    let i = rowData.findIndex((r) => r.mediafile.id === selected);
    let newRows: IRow[] = [];

    if (i < 0) {
      // useOrbitData's snapshot can lag a just-created mediafile (deferred
      // general-resource upload → configure). Fall back to the cache.
      const media =
        mediafiles.find((m) => m.id === selected) ??
        (findRecord(memory, 'mediafile', selected) as MediaFileD | undefined);
      if (media) {
        newRows = oneMediaRow({
          newRow: state.rowData,
          r: null,
          media,
          sourceversion: 0,
          mediafiles,
          artifactTypes,
          categories,
          userResources,
          user,
          localizedCategory: localizedArtifactCategory,
          localizedType: localizedArtifactType,
        });
        i = newRows.length - 1;
      } else {
        oldVernReset();
        fetchBlob('');
        setState((state: ICtxState) => {
          return {
            ...state,
            audioBlob: undefined,
            index: -1,
            selected,
            playerMediafile: undefined,
            playing: false,
            itemPlaying: false,
            commentPlaying: false,
            playItem: '',
            commentPlayId: '',
            loading: false,
          };
        });
        return;
      }
    }
    // i indexes newRows when a row was just built for this media.
    const r = (newRows.length > 0 ? newRows : rowData)[i] as IRow;
    let resetBlob = false;
    //if this is a file that will be played in the wavesurfer..fetch it
    if (inPlayer === PlayInPlayer.yes) {
      inPlayerRef.current = r.mediafile.id;
      if (
        blobState.id !== r.mediafile.id &&
        fetching.current !== r.mediafile.id
      ) {
        fetching.current = r.mediafile.id;
        fetchBlob(r.mediafile.id);
        resetBlob = true;
      }

      if (resetBlob) currentSegmentRef.current = undefined;
      const rows = newRows.length > 0 ? newRows : rowData;
      setState((state: ICtxState) => {
        return {
          ...state,
          audioBlob: resetBlob ? undefined : state.audioBlob,
          index: i,
          selected,
          playerMediafile: (rows[i] as IRow).mediafile,
          playing: false,
          loading: fetching.current !== '',
          rowData: rows,
          currentSegment: resetBlob ? '' : state.currentSegment,
          currentSegmentIndex: resetBlob ? 0 : state.currentSegmentIndex,
        };
      });
    } else if (mediaStart.current !== undefined && !r.isResource) {
      //play just the segment of an old one
      setState((state: ICtxState) => {
        return {
          ...state,
          index: i,
          selected,
          playing: false,
          commentPlaying: false,
          itemPlaying: false,
          oldVernacularPlayItem: r.mediafile.id,
          oldVernacularStart: mediaStart.current || 0,
          rowData: newRows.length > 0 ? newRows : rowData,
        };
      });
    } else if (r.isComment || r.isKeyTerm) {
      setState((state: ICtxState) => {
        return {
          ...state,
          index: i,
          selected,
          playing: false,
          commentPlayId: r.mediafile.id,
          commentPlaying: true, //should I have a useEffect like playItem?
          itemPlaying: false,
          rowData: newRows.length > 0 ? newRows : rowData,
        };
      });
    } else {
      setState((state: ICtxState) => {
        return {
          ...state,
          index: i,
          selected,
          playing: false,
          commentPlaying: false,
          playItem: r.mediafile.id,
          itemPlaying: false, //useEffect will turn this on
          rowData: newRows.length > 0 ? newRows : rowData,
        };
      });
    }
  };

  const setPlayItem = (playItem: string) => {
    setState((state: ICtxState) => {
      return {
        ...state,
        playItem: playItem,
      };
    });
  };

  const setCommentPlayId = (mediaId: string) => {
    setState((state: ICtxState) => {
      return {
        ...state,
        commentPlayId: mediaId,
      };
    });
  };

  const oldVernReset = () => {
    mediaStart.current = undefined;
    mediaEnd.current = undefined;
    mediaPosition.current = undefined;
    handleOldVernacularPlayEnd();
  };

  const setMediaSelected = (id: string, start: number, end: number) => {
    mediaStart.current = start;
    mediaEnd.current = end;
    setSelected(id, PlayInPlayer.no, state.rowData);
  };

  const handleLoaded = () => {
    setState((state: ICtxState) => {
      return {
        ...state,
        oldVernacularPlaying: true,
      };
    });
  };

  const setCurrentSegment = (
    segment: IRegion | undefined,
    currentSegmentIndex: number
  ) => {
    if (
      settingSegmentRef.current &&
      ((!segment && highlightRef.current === undefined) ||
        (segment && segment.start === highlightRef.current))
    ) {
      settingSegmentRef.current = false;
    }
    if (!settingSegmentRef.current && segment?.start !== highlightRef.current) {
      handleHighlightDiscussion(undefined);
      settingSegmentRef.current = false;
    }
    if (
      currentSegmentRef.current !== segment ||
      currentSegmentIndexRef.current !== currentSegmentIndex
    ) {
      currentSegmentRef.current = segment;
      currentSegmentIndexRef.current = currentSegmentIndex;
      currentSegmentSeqRef.current += 1;
      setState((state: ICtxState) => ({
        ...state,
        currentSegment: prettySegment(segment),
        currentSegmentIndex,
        currentSegmentSeq: currentSegmentSeqRef.current,
      }));
    }
  };
  const setupLocate = (cb?: (segments: string) => void) => {
    segmentsCb.current = cb;
  };
  //set the player segment to the specified segment??
  const setPlayerSegments = (segments: string) => {
    if (segmentsCb.current) segmentsCb.current(segments);
    settingSegmentRef.current = false;
  };

  const getCurrentSegment = () => {
    return currentSegmentRef.current;
  };

  const toggleDone = (id: string) => {
    const newRows = state.rowData.map((r) =>
      r.id === id ? { ...r, done: !r.done } : r
    );
    setState((state: ICtxState) => ({ ...state, rowData: newRows }));
  };

  const stepCmp = (a: StepComplete, b: StepComplete) =>
    a.stepid > b.stepid ? 1 : -1;

  useEffect(() => {
    const passageId =
      remoteIdGuid('passage', pasId ?? '', memory?.keyMap as RecordKeyMap) ||
      pasId ||
      '';
    const p = passages.find((p) => p.id === passageId);
    if (p) {
      const complete = getStepComplete(p).sort(stepCmp);
      const s = sections.find((s) => s.id === related(p, 'section'));
      if (s) {
        if (p.id !== state.passage.id || s.id !== state.section.id) {
          setState((state: ICtxState) => {
            const sharedResource = findRecord(
              memory,
              'sharedresource',
              related(p, 'sharedResource')
            ) as SharedResourceD;
            return {
              ...state,
              passage: p as PassageD,
              section: s as SectionD,
              sharedResource,
              psgCompleted: [...complete],
            };
          });
        } else {
          const sortedPrev = [...state.psgCompleted].sort(stepCmp);
          const sortedNew = [...complete].sort(stepCmp);
          const sameAsOrbit =
            sortedPrev.length === sortedNew.length &&
            sortedPrev.every((c, i) => shallowEqual(c, sortedNew[i]));
          if (!sameAsOrbit) {
            setState((state: ICtxState) => ({
              ...state,
              psgCompleted: [...complete],
            }));
          }
        }
      }
    }
    // Intentionally omit state.psgCompleted from deps: this effect writes psgCompleted;
    // listing it retriggers every sync and causes "Maximum update depth exceeded".
    // eslint-disable-next-line react-hooks/exhaustive-deps -- sync from orbit only; see comment above
  }, [memory, pasId, passages, sections, state.passage.id, state.section.id]);

  useEffect(() => {
    if (!booksLoaded) {
      fetchBooks(lang);
    } else {
      setState((state: ICtxState) => {
        return { ...state, allBookData };
      });
    }
    /* eslint-disable-next-line react-hooks/exhaustive-deps */
  }, [lang, booksLoaded, allBookData]);

  useEffect(() => {
    if (blobState.blobStat === BlobStatus.FETCHED) {
      setState((state: ICtxState) => {
        return {
          ...state,
          loading: false,
          audioBlob: blobState.blob,
          playing: false,
        };
      });
      fetching.current = '';
    } else if (blobState.blobStat === BlobStatus.ERROR) {
      const errText = blobState?.error || 'Blob loading error';
      if (errText.startsWith('no offline file'))
        showMessage(sharedStr.fileNotFound);
      else showMessage(errText);
      logError(Severity.error, errorReporter, errText);
      setState((state: ICtxState) => {
        return {
          ...state,
          loading: false,
          audioBlob: undefined,
          playing: false,
        };
      });
      fetching.current = '';
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [blobState]);

  useEffect(() => {
    if (saveResult) {
      logError(Severity.error, errorReporter, saveResult);
      showMessage(saveResult);
      setSaveResult('');
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [saveResult]);

  useEffect(() => {
    const passageId =
      remoteIdGuid('passage', pasId ?? '', memory?.keyMap as RecordKeyMap) ||
      pasId ||
      '';
    const passRec = passages.find((p) => p.id === passageId);
    let psgId = undefined;
    if (related(passRec, 'sharedResource')) {
      const sr = findRecord(
        memory,
        'sharedresource',
        related(passRec, 'sharedResource')
      ) as SharedResourceD;
      psgId = related(sr, 'passage');
    }
    const allMedia = getAllMediaRecs(psgId ?? passageId, memory);
    const localize = {
      localizedCategory: localizedArtifactCategory,
      localizedType: localizedArtifactType,
    };
    const pres = getProjectResources();
    let newData = mediaRows({
      artifactTypes,
      categories,
      userResources,
      mediafiles: allMedia.concat(pres) as MediaFileD[],
      user,
      ...localize,
    });

    const sectId = related(passRec, 'section');
    const res = getResources(sectionResources, mediafiles, sectId);
    newData = newData.concat(
      resourceRows({
        artifactTypes,
        categories,
        userResources,
        mediafiles,
        res,
        user,
        ...localize,
      }).sort((i, j) => i.sequenceNum - j.sequenceNum)
    );

    const mediafileId =
      newData.length > 0 && (newData[0] as IRow).isVernacular
        ? (newData[0] as IRow).id
        : '';
    const i = state.selected
      ? newData.findIndex((r) => r.mediafile.id === state.selected)
      : state.index;
    const willSetSelected =
      state.tool !== ToolSlug.Resource &&
      state.tool !== ToolSlug.Transcribe &&
      mediafileId !== state.playerMediafile?.id;
    setState((state: ICtxState) => {
      return { ...state, rowData: newData, index: i, mediafileId };
    });

    if (willSetSelected) {
      setSelected(mediafileId, PlayInPlayer.yes, newData);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sectionResources, mediafiles, pasId, userResources]);

  useEffect(() => {
    let delayedPlay: NodeJS.Timeout | undefined = undefined;
    //if I set playing when I set the mediaId, it plays a bit of the old
    //if not starting at the beginning set to playing after loaded
    if (state.playItem && mediaStart.current === undefined)
      delayedPlay = setTimeout(() => {
        setItemPlaying(true);
      }, 2000);

    return () => {
      if (delayedPlay) clearTimeout(delayedPlay);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state.playItem]);

  useEffect(() => {
    if (state.orgWorkflowSteps !== filteredOrgSteps) {
      setState((state) => ({ ...state, orgWorkflowSteps: filteredOrgSteps }));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filteredOrgSteps]);

  useEffect(() => {
    const wf: SimpleWf[] = state.orgWorkflowSteps.map((s) => ({
      id: s.id,
      label: s.attributes.name,
    }));
    setState((state: ICtxState) => ({ ...state, workflow: wf }));
  }, [state.orgWorkflowSteps]);

  useEffect(() => {
    return () => {
      forceClearPending();
    };
  }, []);

  useEffect(() => {
    if (state.currentstep === '' && state.orgWorkflowSteps.length > 0) {
      const next = getNextStep(state);
      if (state.currentstep !== next) {
        handleSetCurrentStep(
          next || (state.orgWorkflowSteps[0] as OrgWorkflowStepD).id
        );
      }
      segmentsCb.current = undefined;
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state.currentstep, state.psgCompleted, state.orgWorkflowSteps]);

  if (view.current !== '') {
    const target = view.current;
    view.current = '';
    return <StickyRedirect to={target} />;
  }

  return (
    <PassageDetailContext.Provider
      value={{
        state: {
          ...state,
          canPublish,
          setSelected,
          setCurrentStep,
          setFirstStepIndex,
          setDiscussionSize,
          setChooserSize,
          setPlaying,
          setItemPlaying,
          setPlayItem,
          setCommentPlaying,
          setCommentPlayId,
          setPDBusy,
          setCurrentSegment,
          getCurrentSegment,
          setPlayerSegments,
          setupLocate,
          stepComplete,
          setStepComplete,
          setStepCompleteTo,
          gotoNextStep,
          setRecording,
          setCommentRecording,
          isNavigationBlocked,
          setMediaSelected,
          toggleDone,
          handleItemPlayEnd,
          handleItemTogglePlay,
          handleCommentPlayEnd,
          handleCommentTogglePlay,
          handleOldVernacularPlayEnd,
          setDiscussionMarkers,
          handleHighlightDiscussion,
          forceRefresh,
          setDiscussOpen,
          setPromptPlaybackComplete,
          setPromptDockedRecordButton,
          promptDockedRecordButton: promptDockedRecordButtonRef.current,
          promptDockedRecordFooterVersion,
          isBoldWorkflow,
          hideMobileHeader: state.hideMobileHeader,
          setHideMobileHeader,
          sectionArr: (getProjectDefault(projDefSectionMap) ??
            []) as SectionArray,
          setCarefulSpeechSegParams,
        },
        setState,
      }}
    >
      {props.children}
      {/*this is only used to play old vernacular file segments*/}
      <LimitedMediaPlayer
        srcMediaId={state.oldVernacularPlayItem}
        requestPlay={state.oldVernacularPlaying}
        onEnded={handleOldVernacularPlayEnd}
        onLoaded={handleLoaded}
        limits={{ start: mediaStart.current, end: mediaEnd.current }}
      />
      {confirm !== '' && (
        <Confirm
          title={wfStr.unsaved}
          text={wfStr.saveFirst}
          yesResponse={handleConfirmStep}
          noResponse={handleRefuseStep}
        />
      )}
      <StepNavigationConfirmDialog
        open={incompleteNavTarget !== ''}
        message={incompleteNavMessage}
        onCancel={handleIncompleteNavCancel}
        onComplete={handleIncompleteNavComplete}
        onContinue={handleIncompleteNavContinue}
      />
    </PassageDetailContext.Provider>
  );
};

export { PassageDetailContext, PassageDetailProvider };

/* eslint-disable @typescript-eslint/no-unused-vars */
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useGlobal } from '../context/useGlobal';
import {
  ProjectD,
  DiscussionD,
  MediaFileD,
  GroupMembershipD,
  Plan,
  PlanType,
} from '../model';
import { findRecord, usePlanType } from '../crud';
import {
  projDefSectionMap,
  useProjectDefaults,
} from '../crud/useProjectDefaults';
import { useOrbitData } from '../hoc/useOrbitData';
import { LocalKey, localUserKey } from '../utils';
import { useProjectPermissions } from '../utils/useProjectPermissions';
import { SectionArray } from '../model/SectionArray';
export interface IRowData {}

const initState = {
  connected: false,
  mediafiles: [] as MediaFileD[],
  discussions: [] as DiscussionD[],
  groupmemberships: [] as GroupMembershipD[],
  scripture: false,
  flat: false,
  shared: false,
  publishingOn: true,
  hidePublishing: true,
  canEditSheet: false,
  canEditAudio: false,
  canPublish: false,
  sectionArr: [] as SectionArray,
  setSectionArr: (_sectionArr: SectionArray) => {},
  togglePublishing: () => {},
  setCanAddPublishing: (_canAddPublishing: boolean) => {},
  tab: 0,
  setTab: (_tab: number) => {},
};

export type ICtxState = typeof initState;

interface IContext {
  state: ICtxState;
  setState: React.Dispatch<React.SetStateAction<ICtxState>>;
}

const PlanContext = React.createContext({
  state: initState as ICtxState,
  setState: () => {},
} as IContext);

interface IProps {
  children: React.ReactElement;
}

const EMPTY_SECTION_ARR: SectionArray = [];

const PlanProvider = (props: IProps) => {
  const mediafiles = useOrbitData<MediaFileD[]>('mediafile');
  const discussions = useOrbitData<DiscussionD[]>('discussion');
  const groupmemberships = useOrbitData<GroupMembershipD[]>('groupmembership');
  const projects = useOrbitData<ProjectD[]>('project');
  // Re-read flat/scripture when plan or plantype records arrive (TT-7641).
  // Depending only on plan id left scripture=false until a full remount.
  const plans = useOrbitData<Plan[]>('plan');
  const planTypes = useOrbitData<PlanType[]>('plantype');
  const [memory] = useGlobal('memory');
  const [plan] = useGlobal('plan'); //will be constant here
  const [project] = useGlobal('project'); //will be constant here
  const [connected] = useGlobal('connected'); //verified this is not used in a function 2/18/25
  const [isOffline] = useGlobal('offline'); //verified this is not used in a function 2/18/25
  const [offlineOnly] = useGlobal('offlineOnly');
  const [isDeveloper] = useGlobal('developer');
  const getPlanType = usePlanType();
  const { setProjectDefault, getProjectDefault } = useProjectDefaults();
  const {
    canEditSheet: canEditSheetPerm,
    canEditSheetBase,
    canPublish,
  } = useProjectPermissions();
  const [addStoryOrPassage] = useGlobal('addStoryOrPassage');
  // Bold-workflow members can add sections/passages when the session-only
  // "Add {Story} or Passage" flag is set (see UserMenu). The flag can only be
  // set in a bold context, so no extra workflow guard is needed here.
  // Structural sheet edits (adding/moving sections & passages) still require
  // connectivity to the server, same as admins/sheet-editors -- see TT-7521.
  // Audio upload/delete is safe to allow offline (it queues for later sync),
  // so canEditAudio intentionally does not apply that restriction.
  const structuralOffline = isOffline && !offlineOnly;
  const canEditSheet =
    canEditSheetPerm || (addStoryOrPassage && !structuralOffline);
  const canEditAudio = canEditSheetBase || addStoryOrPassage;
  const [state, setState] = useState(() => {
    const { scripture, flat } = getPlanType(plan);
    return {
      ...initState,
      mediafiles,
      discussions,
      groupmemberships,
      scripture,
      flat,
    };
  });
  // Keep sectionArr in React state so consumers see a stable reference between
  // real updates (getProjectDefault JSON-parses a new array every call).
  const [sectionArr, setSectionArrState] =
    useState<SectionArray>(EMPTY_SECTION_ARR);

  const setTab = (tab: number) => {
    setState((state) => ({ ...state, tab }));
  };

  const defaultParams = projects.find((p) => p.id === project)?.attributes
    ?.defaultParams;

  useEffect(() => {
    const map = getProjectDefault(projDefSectionMap) as
      SectionArray | undefined;
    const next = map?.length ? map : EMPTY_SECTION_ARR;
    setSectionArrState((prev) =>
      JSON.stringify(prev) === JSON.stringify(next) ? prev : next
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [project, defaultParams]);

  const setSectionArr = useCallback(
    (newArr: SectionArray) => {
      const next = newArr.length ? newArr : EMPTY_SECTION_ARR;
      setSectionArrState((prev) => {
        if (JSON.stringify(prev) === JSON.stringify(next)) return prev;
        return next;
      });
      // Persist outside the updater. Empty map stays [] (do not delete the key).
      const prev = getProjectDefault(projDefSectionMap) as
        SectionArray | undefined;
      const prevNorm = prev?.length ? prev : EMPTY_SECTION_ARR;
      if (JSON.stringify(prevNorm) === JSON.stringify(next)) return;
      setProjectDefault(projDefSectionMap, next);
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    []
  );

  useEffect(() => {
    const { scripture, flat } = getPlanType(plan);
    setState((prev) =>
      flat === prev.flat && scripture === prev.scripture
        ? prev
        : { ...prev, flat, scripture }
    );
    // plans/planTypes: re-run when Orbit has the plan or plantype (Book column).
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [plan, plans, planTypes]);

  useEffect(() => {
    const projRec = findRecord(memory, 'project', project) as ProjectD;
    if (projRec) {
      const shared = projRec?.attributes?.isPublic || false;
      const hideId = LocalKey.hidePublishing + project;
      const hidePublish =
        localStorage.getItem(localUserKey(hideId as LocalKey)) || 'true';
      const hidePublishing = Boolean(
        hidePublish === 'true' || (isOffline && !isDeveloper)
      );

      if (
        shared !== state.shared ||
        hidePublishing !== state[LocalKey.hidePublishing]
      ) {
        setState((state) => ({
          ...state,
          shared,
          hidePublishing,
        }));
        localStorage.setItem(
          localUserKey(hideId as LocalKey),
          hidePublishing.toString()
        );
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [project]);

  const setCanAddPublishing = (publishingOn: boolean) => {
    setState((state) => ({ ...state, publishingOn }));
  };

  const togglePublishing = () => {
    const { hidePublishing } = state;
    const hideId = LocalKey.hidePublishing + project;
    localStorage.setItem(
      localUserKey(hideId as LocalKey),
      (!hidePublishing).toString()
    );
    setState((state) => ({ ...state, hidePublishing: !hidePublishing }));
  };

  const ctxState = useMemo(
    () => ({
      ...state,
      sectionArr,
      setSectionArr,
      connected,
      canEditSheet,
      canEditAudio,
      canPublish,
      togglePublishing,
      setCanAddPublishing,
      setTab,
    }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [
      state,
      sectionArr,
      setSectionArr,
      connected,
      canEditSheet,
      canEditAudio,
      canPublish,
    ]
  );

  return (
    <PlanContext.Provider
      value={{
        state: ctxState,
        setState,
      }}
    >
      {props.children}
    </PlanContext.Provider>
  );
};

export { PlanContext, PlanProvider };

