        mixing[mixingOffset + 1] * compare[i + 1];
    }
    return corr;
  }

  // TODO inline
  /**
   * Overlaps samples in 'midBuffer' with the samples in 'pInputBuffer' at position
   * of 'ovlPos'.
   */
  overlap(ovlPos) {
    this.overlapStereo(2 * ovlPos);
  }

  /**
   * Overlaps samples in 'midBuffer' with the samples in 'pInput'
   */
  overlapStereo(pInputPos) {
    const pInput = this._inputBuffer.vector;
    pInputPos += this._inputBuffer.startIndex;

    var pOutput = this._outputBuffer.vector,
      pOutputPos = this._outputBuffer.endIndex,
      i,
      cnt2,
      fTemp,
      fScale,
      fi,
      pInputOffset,
      pOutputOffset;

    fScale = 1 / this.overlapLength;
    for (i = 0; i < this.overlapLength; i++) {
      fTemp = (this.overlapLength - i) * fScale;
      fi = i * fScale;
      cnt2 = 2 * i;
      pInputOffset = cnt2 + pInputPos;
      pOutputOffset = cnt2 + pOutputPos;
      pOutput[pOutputOffset + 0] =
        pInput[pInputOffset + 0] * fi + this.pMidBuffer[cnt2 + 0] * fTemp;
      pOutput[pOutputOffset + 1] =
        pInput[pInputOffset + 1] * fi + this.pMidBuffer[cnt2 + 1] * fTemp;
    }
  }
  process() {
    var ovlSkip, offset, temp;
    if (this.pMidBuffer === null) {
      // if midBuffer is empty, move the first samples of the input stream
      // into it
      if (this._inputBuffer.frameCount < this.overlapLength) {
        // wait until we've got overlapLength samples
        return;
      }
      this.pMidBuffer = new Float32Array(this.overlapLength * 2);
      this._inputBuffer.receiveSamples(this.pMidBuffer, this.overlapLength);
    }

    // Process samples as long as there are enough samples in 'inputBuffer'
    // to form a processing frame.
    while (this._inputBuffer.frameCount >= this.sampleReq) {
      // If tempo differs from the normal ('SCALE'), scan for the best overlapping
      // position
      offset = this.seekBestOverlapPosition();

      // Mix the samples in the 'inputBuffer' at position of 'offset' with the
      // samples in 'midBuffer' using sliding overlapping
      // ... first partially overlap with the end of the previous sequence
      // (that's in 'midBuffer')
      this._outputBuffer.ensureAdditionalCapacity(this.overlapLength);
      // FIXME unit?
      //overlap(uint(offset));
      this.overlap(Math.floor(offset));
      this._outputBuffer.put(this.overlapLength);

      // ... then copy sequence samples from 'inputBuffer' to output
      temp = this.seekWindowLength - 2 * this.overlapLength; // & 0xfffffffe;
      if (temp > 0) {
        this._outputBuffer.putBuffer(
          this._inputBuffer,
          offset + this.overlapLength,
          temp
        );
      }

      // Copies the end of the current sequence from 'inputBuffer' to
      // 'midBuffer' for being mixed with the beginning of the next
      // processing sequence and so on
      //assert(offset + seekWindowLength <= (int)inputBuffer.numSamples());
      const start =
        this.inputBuffer.startIndex +
        2 * (offset + this.seekWindowLength - this.overlapLength);
      this.pMidBuffer.set(
        this._inputBuffer.vector.subarray(start, start + 2 * this.overlapLength)
      );

      // Remove the processed samples from the input buffer. Update
      // the difference between integer & nominal skip step to 'skipFract'
      // in order to prevent the error from accumulating over time.
      this.skipFract += this.nominalSkip; // real skip size
      ovlSkip = Math.floor(this.skipFract); // rounded to integer skip
      this.skipFract -= ovlSkip; // maintain the fraction part, i.e. real vs. integer skip
      this._inputBuffer.receive(ovlSkip);
    }
  }
  get tempo() {
    return this._tempo;
  }
}
export class SoundTouch {
  constructor(sampleRate) {
    this.rateTransposer = new RateTransposer(false);
    this.tdStretch = new Stretch(false, sampleRate);

    this._inputBuffer = new FifoSampleBuffer();
    this._intermediateBuffer = new FifoSampleBuffer();
    this._outputBuffer = new FifoSampleBuffer();

    this._rate = 0;
    this._tempo = 0;

    this.virtualPitch = 1.0;
    this.virtualRate = 1.0;
    this.virtualTempo = 1.0;

    this._calculateEffectiveRateAndTempo();
  }

  extend(a, b) {
    for (const i in b) {
      const g = b.__lookupGetter__(i),
        s = b.__lookupSetter__(i);
      if (g || s) {
        if (g) {
          a.__defineGetter__(i, g);
        }
        if (s) {
          a.__defineSetter__(i, s);
        }
      } else {
        a[i] = b[i];
      }
    }
    return a;
  }

  clear() {
    this.rateTransposer.clear();
    this.tdStretch.clear();
  }
  get rate() {
    return this._rate;
  }
  set rate(rate) {
    this.virtualRate = rate;
    this._calculateEffectiveRateAndTempo();
  }
  set rateChange(rateChange) {
    this.rate = 1.0 + 0.01 * rateChange;
  }
  get tempo() {
    return this._tempo;
  }
  set tempo(tempo) {
    this.virtualTempo = tempo;
    this._calculateEffectiveRateAndTempo();
  }
  set tempoChange(tempoChange) {
    this.tempo = 1.0 + 0.01 * tempoChange;
  }
  set pitch(pitch) {
    this.virtualPitch = pitch;
    this._calculateEffectiveRateAndTempo();
  }
  set pitchOctaves(pitchOctaves) {
    this.pitch = Math.exp(0.69314718056 * pitchOctaves);
    this._calculateEffectiveRateAndTempo();
  }
  set pitchSemitones(pitchSemitones) {
    this.pitchOctaves = pitchSemitones / 12.0;
  }
  get inputBuffer() {
    return this._inputBuffer;
  }
  get outputBuffer() {
    return this._outputBuffer;
  }
  _calculateEffectiveRateAndTempo() {
    const testFloatEqual = (a, b) => {
      return (a > b ? a - b : b - a) > 1e-10;
    };
    const previousTempo = this._tempo;
    const previousRate = this._rate;

    this._tempo = this.virtualTempo / this.virtualPitch;
    this._rate = this.virtualRate * this.virtualPitch;

    if (testFloatEqual(this._tempo, previousTempo)) {
      this.tdStretch.tempo = this._tempo;
    }
    if (testFloatEqual(this._rate, previousRate)) {
      this.rateTransposer.rate = this._rate;
    }

    if (this._rate > 1.0) {
      if (this._outputBuffer !== this.rateTransposer.outputBuffer) {
        this.tdStretch.inputBuffer = this._inputBuffer;
        this.tdStretch.outputBuffer = this._intermediateBuffer;

        this.rateTransposer.inputBuffer = this._intermediateBuffer;
        this.rateTransposer.outputBuffer = this._outputBuffer;
      }
    } else {
      if (this._outputBuffer !== this.tdStretch.outputBuffer) {
        this.rateTransposer.inputBuffer = this._inputBuffer;
        this.rateTransposer.outputBuffer = this._intermediateBuffer;

        this.tdStretch.inputBuffer = this._intermediateBuffer;
        this.tdStretch.outputBuffer = this._outputBuffer;
      }
    }
  }
  process() {
    if (this._rate > 1.0) {
      this.tdStretch.process();
      this.rateTransposer.process();
    } else {
      this.rateTransposer.process();
      this.tdStretch.process();
    }
  }
  getWebAudioNode(context, filter) {
    const BUFFER_SIZE = 4096;
    const node = context.createScriptProcessor(BUFFER_SIZE, 2, 2),
      samples = new Float32Array(BUFFER_SIZE * 2);
    node.onaudioprocess = function (e) {
      const l = e.outputBuffer.getChannelData(0),
        r = e.outputBuffer.getChannelData(1);
      const framesExtracted = filter.extract(samples, BUFFER_SIZE);
      if (framesExtracted === 0) {
        node.disconnect(); // Pause.
      }
      for (var i = 0; i < framesExtracted; i++) {
        l[i] = samples[i * 2];
        r[i] = samples[i * 2 + 1];
      }
    };
    return node;
  }
}

import { AvatarProps, SxProps } from '@mui/material';

function stringToColor(string: string): string {
  let hash = 0;
  let i;

  /* eslint-disable no-bitwise */
  for (i = 0; i < string.length; i += 1) {
    hash = string.charCodeAt(i) + ((hash << 5) - hash);
  }

  let color = '#';

  for (i = 0; i < 3; i += 1) {
    const value = (hash >> (i * 8)) & 0xff;
    color += `00${value.toString(16)}`.slice(-2);
  }
  /* eslint-enable no-bitwise */

  return color;
}

const initials = (name: string): string => {
  const [firstName, lastName] = name.split(' ');
  if (firstName && lastName) return `${firstName[0]}${lastName[0]}`;
  if (firstName) return `${firstName[0]}`;
  return '';
};

export function stringAvatar(name: string, sxProps?: SxProps): AvatarProps {
  return {
    sx: { ...sxProps, bgcolor: stringToColor(name) },
    children: `${initials(name)}`,
  };
}

import { useGetGlobal, useGlobal } from '../context/useGlobal';
import * as actions from '../store';
import Axios from 'axios';
import JSONAPISource from '@orbit/jsonapi';
import { API_CONFIG, OrbitNetworkErrorRetries } from '../../api-variable';
import { useDispatch } from 'react-redux';
import { LocalKey } from '../utils';
import Bugsnag from '@bugsnag/js';
import { orbitReset } from '../crud/orbitReset';

export function Online(doCheck: boolean, cb: (result: boolean) => void): void {
  const opts = {
    timeout: 10000,
  };

  //if we're electron, don't be using the internet even if it's available
  //until the user logs in or the override is true
  if (!doCheck) {
    cb(false);
  }

  Axios.get(API_CONFIG.host + '/api/AmIOnline/', opts)
    .then(() => {
      cb(true);
    })
    .catch((reason) => {
      cb(reason.response !== undefined);
    });
}
// eslint-disable-next-line @typescript-eslint/explicit-function-return-type, @typescript-eslint/no-unused-vars
export const useCheckOnline = (label: string) => {
  const dispatch = useDispatch();
  const resetOrbitError = actions.resetOrbitError;
  const getGlobal = useGetGlobal();
  const [, setConnected] = useGlobal('connected');
  const [, setOrbitRetries] = useGlobal('orbitRetries');
  const [coordinator] = useGlobal('coordinator');
  const remote = coordinator?.getSource('remote') as JSONAPISource;

  const errorReset = async () => {
    dispatch(resetOrbitError());
    await orbitReset(remote, setOrbitRetries);
    // queue.retry() can re-dispatch ORBIT_RETRY via Sources updateError; clear
    // again so a later Record remount does not re-snack (TT-7720).
    dispatch(resetOrbitError());
  };

  const checkOnline = (
    cb: (result: boolean) => void,
    forceCheck: boolean = false
  ): void => {
    if (!forceCheck && getGlobal('offline')) {
      localStorage.setItem(LocalKey.connected, 'false');
    }
    const statusChange = (result: boolean) => {
      localStorage.setItem(
        LocalKey.connected,
        `${result && !getGlobal('offline')}`
      );
      if (API_CONFIG.snagId !== '') {
        if (result) {
          Bugsnag.resumeSession();
        } else {
          Bugsnag.pauseSession();
        }
      }
      setConnected(result);
    };
    //console.log('Checking online status for ' + label);
    Online(forceCheck || !getGlobal('offline'), (result) => {
      // TT-7720: clear stale orbit network-error snack when AmIOnline succeeds
      // even if `connected` is already true (Pending Retry / CloudOff paths).
      // Only run full orbitReset (queue.retry) on a false→true edge — retrying
      // the queue while already online re-fires non-network failures (e.g. 403
      // on passagestatechanges) and can surface a spurious API Error 500 page.
      if (result) {
        if (getGlobal('connected') !== result) {
          errorReset().finally(() => {
            statusChange(result);
          });
        } else {
          dispatch(resetOrbitError());
          setOrbitRetries(OrbitNetworkErrorRetries);
        }
      } else if (getGlobal('connected') !== result) {
        statusChange(result);
      }
      cb(result);
    });
  };
  return checkOnline;
};

import { NavigateOptions, To, useNavigate } from 'react-router-dom';
import { useHome } from './useHome';
import { useEffect, useState } from 'react';

const cancelListeners = new Set<() => void>();

/* A navigation issued through useMyNavigate was blocked and the user chose to stay. */
export const navigationCancelled = (): void => {
  cancelListeners.forEach((cb) => cb());
};

export const useMyNavigate = (): typeof myNavigate => {
  const navigate = useNavigate();
  const { checkHome } = useHome();
  const [goTo, setGoTo] = useState<{
    to: To;
    options: NavigateOptions | undefined;
  }>();

  useEffect(() => {
    if (goTo) navigate(goTo.to, goTo.options);
  }, [goTo]);

  useEffect(() => {
    const clear = () => setGoTo(undefined);
    cancelListeners.add(clear);
    return () => {
      cancelListeners.delete(clear);
    };
  }, []);

  function myNavigate(to: To, options?: NavigateOptions): void {
    checkHome(to);
    if (to !== goTo?.to) setGoTo({ to, options });
  }
  return myNavigate;
};

import { useEffect, useRef } from 'react';

/**
 * Helps tracking the props changes made in a react functional component.
 *
 * Prints the name of the properties/states variables causing a render (or re-render).
 * For debugging purposes only.
 *
 * @usage You can simply track the props of the components like this:
 *  useRenderingTrace('MyComponent', props);
 *
 * @usage You can also track additional state like this:
 *  const [someState] = useState(null);
 *  useRenderingTrace('MyComponent', { ...props, someState });
 *
 * @param componentName Name of the component to display
 * @param propsAndStates
 * @param level
 *
 * @see https://stackoverflow.com/a/51082563/2391795
 */
function useRenderingTrace<
  T extends Record<string, unknown>,
  L extends 'debug' | 'info' | 'log' = 'debug',
>(componentName: string, propsAndStates: T, level: L = 'debug' as L): void {
  const prev = useRef<T>(propsAndStates);

  useEffect(() => {
    type Diff = { [K in keyof T]?: { old: T[K] | undefined; new: T[K] } };
    const changedProps = (
      Object.entries(propsAndStates) as Array<[keyof T, T[keyof T]]>
    ).reduce<Diff>((acc, [key, value]) => {
      if (prev.current[key] !== value) {
        acc[key] = { old: prev.current[key], new: value };
      }
      return acc;
    }, {});
    if (Object.keys(changedProps).length > 0) {
      // eslint-disable-next-line no-console
      console[level](`[${componentName}] Changed props:`, changedProps);
    } else {
      // eslint-disable-next-line no-console
      console[level](`[${componentName}] no changed props:`);
    }

    prev.current = propsAndStates;
  });
}

export default useRenderingTrace;

import { useEffect, useRef } from 'react';

// To print out what props are changing
// usage: useTraceUpdate(props) inside your component
export function useTraceUpdate<T extends Record<string, unknown>>(
  props: T
): void {
  const prev = useRef<T>(props);

  useEffect(() => {
    const changedProps: Partial<
      Record<keyof T, [T[keyof T] | undefined, T[keyof T]]>
    > = {};

    (Object.keys(props) as Array<keyof T>).forEach((k) => {
      if (prev.current[k] !== props[k]) {
        changedProps[k] = [prev.current[k], props[k]];
      }
    });

    if (Object.keys(changedProps).length > 0) {
      // eslint-disable-next-line no-console
      console.log('Changed props:');
      (Object.keys(changedProps) as Array<keyof T>).forEach((key) => {
        // eslint-disable-next-line no-console
        console.log(String(key), changedProps[key]);
      });
    }
    prev.current = props;
  });
}

export function validateEmail(email: string): boolean {
  /* eslint-disable-next-line no-useless-escape */
  const re =
    /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;
  return re.test(email.toLowerCase());
}
export function validateMultipleEmails(emails: string): boolean {
  const emailList = emails.split(';');
  for (const email of emailList) {
    if (!validateEmail(email.trim())) {
      return false;
    }
  }
  return true;
}
